function applyDraft(d){$('siteDirection').value=d.direction||'auto';$('siteMood').value=d.mood||'auto';$('siteDensity').value=d.density||'balanced';$('siteMotion').checked=d.motion!==false;$('siteStickyNav').checked=d.stickyNav!==false;$('siteEyebrow').value=d.eyebrow||'';$('siteHeadline').value=d.headline||'';$('siteSub').value=d.sub||'';$('siteCta').value=d.cta||'';$('siteServicesTitle').value=d.servicesTitle||'';$('siteServices').value=d.services||'';$('siteDifferentials').value=d.differentials||'';$('siteAboutTitle').value=d.aboutTitle||'';$('siteAbout').value=d.about||'';$('siteFaq').value=d.faq||'';$('siteAccent').value=d.accent||'#7567ff';$('siteAccentText').value=d.accent||'#7567ff';$('siteLogo').value=d.logo?.startsWith('data:')?'':(d.logo||'');$('siteImage').value=d.hero?.startsWith('data:')?'':(d.hero||'');$('siteAboutImage').value=d.aboutImage?.startsWith('data:')?'':(d.aboutImage||'');$('siteGallery').value=(d.gallery||[]).filter(x=>!x.startsWith('data:')).join('\n');$('siteRating').value=d.rating||'';$('siteReviewCount').value=d.reviewCount||'';$('siteTrustLine').value=d.trustLine||'';$('siteStats').value=d.stats||'';$('siteTestimonials').value=d.testimonials||'';$('sitePhone').value=d.phone||'';$('siteInstagram').value=d.instagram||'';$('siteAddress').value=d.address||'';$('siteHours').value=d.hours||'';$('siteFinalCta').value=d.finalCta||'';$('siteMap').checked=d.map!==false;$('siteFloatingWhats').checked=d.floatingWhats!==false;$('siteSeoTitle').value=d.seoTitle||'';$('siteSeoDescription').value=d.seoDescription||'';$('siteCity').value=d.city||'';$('siteFooterText').value=d.footerText||'';assets.logo=d.logo?.startsWith('data:')?d.logo:'';assets.hero=d.hero?.startsWith('data:')?d.hero:'';assets.gallery=(d.gallery||[]).filter(x=>x.startsWith('data:'));}
function draftFromForm(){const l=lead(),old=l?.siteDraft||{},urls=lines($('siteGallery').value),direction=$('siteDirection').value,realDir=directionFor(l,{direction,variantSeed:old.variantSeed||0});return{...old,direction,variantSeed:old.variantSeed||0,mood:$('siteMood').value,density:$('siteDensity').value,motion:$('siteMotion').checked,stickyNav:$('siteStickyNav').checked,accent:$('siteAccent').value,eyebrow:$('siteEyebrow').value,headline:$('siteHeadline').value,sub:$('siteSub').value,cta:$('siteCta').value,servicesTitle:$('siteServicesTitle').value,services:$('siteServices').value,differentials:$('siteDifferentials').value,aboutTitle:$('siteAboutTitle').value,about:$('siteAbout').value,faq:$('siteFaq').value,rating:$('siteRating').value,reviewCount:$('siteReviewCount').value,trustLine:$('siteTrustLine').value,stats:$('siteStats').value,testimonials:$('siteTestimonials').value,phone:$('sitePhone').value,instagram:$('siteInstagram').value,address:$('siteAddress').value,hours:$('siteHours').value,finalCta:$('siteFinalCta').value,map:$('siteMap').checked,floatingWhats:$('siteFloatingWhats').checked,seoTitle:$('siteSeoTitle').value,seoDescription:$('siteSeoDescription').value,city:$('siteCity').value,footerText:$('siteFooterText').value,logo:assets.logo||$('siteLogo').value.trim(),hero:assets.hero||$('siteImage').value.trim(),aboutImage:$('siteAboutImage').value.trim(),gallery:[...assets.gallery,...urls].slice(0,8),_resolvedDirection:realDir};}

function colorMix(hex,amount=20){const h=hex.replace('#','');if(h.length!==6)return hex;const n=parseInt(h,16),r=Math.max(0,Math.min(255,(n>>16)+amount)),g=Math.max(0,Math.min(255,((n>>8)&255)+amount)),b=Math.max(0,Math.min(255,(n&255)+amount));return'#'+[r,g,b].map(x=>x.toString(16).padStart(2,'0')).join('')}
function safe(v){return K.esc(v)}function attr(v){return String(v??'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function image(src,alt,cls=''){return src?`<img class="${cls}" src="${attr(src)}" alt="${attr(alt)}" loading="lazy">`:''}
function initials(name){return String(name||'K').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()}
function buildHero(l,d,dir,t,hero,gal){const logo=d.logo?image(d.logo,l.name,'brand-logo'):`<span class="brand-text">${safe(l.name)}</span>`,w=K.waUrl(d.phone,l.country),button=w?`<a class="btn primary" href="${attr(w)}" target="_blank">${safe(d.cta||t.whatsapp)} <span>↗</span></a>`:'',secondary=`<a class="btn secondary" href="#services">${safe(t.learn)} <span>↓</span></a>`;const copy=`<div class="hero-copy"><div class="eyebrow">${safe(d.eyebrow)}</div><h1>${safe(d.headline)}</h1><p>${safe(d.sub)}</p><div class="hero-actions">${button}${secondary}</div></div>`;const fallback=`<div class="image-placeholder"><span>${safe(initials(l.name))}</span></div>`;if(dir.hero==='fullbleed')return`<section class="hero hero-full">${hero?image(hero,l.name,'hero-bg'):fallback}<div class="hero-overlay"></div><div class="nav-brand">${logo}</div>${copy}<div class="hero-note">${safe(d.trustLine||'')}</div></section>`;if(dir.hero==='splitLuxury'||dir.hero==='softSplit'||dir.hero==='clinical'||dir.hero==='corporate')return`<section class="hero hero-split"><div class="hero-left"><div class="nav-brand mobile-brand">${logo}</div>${copy}</div><div class="hero-right">${hero?image(hero,l.name,'hero-main'):fallback}${gal[0]?`<div class="hero-float">${image(gal[0],l.name,'hero-small')}</div>`:''}</div></section>`;if(dir.hero==='galleryHero'||dir.hero==='fashion')return`<section class="hero hero-gallery"><div class="hero-gallery-copy">${copy}</div><div class="hero-gallery-images">${hero?image(hero,l.name,'hero-main'):fallback}${gal[0]?image(gal[0],l.name,'hero-side'):''}${gal[1]?image(gal[1],l.name,'hero-side second'):''}</div></section>`;if(dir.hero==='kinetic'||dir.hero==='bold'||dir.hero==='friendly')return`<section class="hero hero-bold"><div class="shape shape-a"></div><div class="shape shape-b"></div>${copy}<div class="hero-bold-image">${hero?image(hero,l.name,'hero-main'):fallback}</div></section>`;return`<section class="hero hero-collage">${copy}<div class="collage">${hero?image(hero,l.name,'collage-main'):fallback}${gal[0]?image(gal[0],l.name,'collage-small a'):''}${gal[1]?image(gal[1],l.name,'collage-small b'):''}</div></section>`}
function buildServices(d,dir,t){const sv=pairs(d.services);if(!sv.length)return'';if(['numbered','editorial','horizontal'].includes(dir.services))return`<section class="section services editorial-services reveal" id="services"><div class="section-head"><div class="kicker">${safe(t.services)}</div><h2>${safe(d.servicesTitle)}</h2></div><div class="service-lines">${sv.map((s,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><h3>${safe(s.title)}</h3><p>${safe(s.text)}</p></div><b>↗</b></article>`).join('')}</div></section>`;if(dir.services==='steps')return`<section class="section services steps reveal" id="services"><div class="section-head"><div class="kicker">${safe(t.services)}</div><h2>${safe(d.servicesTitle)}</h2></div><div class="step-grid">${sv.map((s,i)=>`<article><div class="step-num">0${i+1}</div><h3>${safe(s.title)}</h3><p>${safe(s.text)}</p></article>`).join('')}</div></section>`;return`<section class="section services reveal" id="services"><div class="section-head"><div class="kicker">${safe(t.services)}</div><h2>${safe(d.servicesTitle)}</h2></div><div class="service-grid">${sv.map((s,i)=>`<article><span class="service-num">0${i+1}</span><h3>${safe(s.title)}</h3><p>${safe(s.text)}</p></article>`).join('')}</div></section>`}
function buildAbout(l,d,dir,t,hero,gal){const aboutImg=d.aboutImage||gal[1]||gal[0]||hero;return`<section class="section about reveal about-${dir.about}" id="about"><div class="about-media">${aboutImg?image(aboutImg,l.name,'about-img'):`<div class="about-placeholder">${safe(initials(l.name))}</div>`}</div><div class="about-copy"><div class="kicker">${safe(t.about)}</div><h2>${safe(d.aboutTitle)}</h2><p>${safe(d.about)}</p><div class="mini-contact">${d.address?`<span>⌖ ${safe(d.address)}</span>`:''}${d.phone?`<span>✆ ${safe(d.phone)}</span>`:''}${d.instagram?`<span>◎ @${safe(K.igHandle(d.instagram))}</span>`:''}</div></div></section>`}
function buildProof(d,t){const dif=pairs(d.differentials),stats=pairs(d.stats),test=pairs(d.testimonials),rating=d.rating||'',reviews=d.reviewCount||'';if(!dif.length&&!stats.length&&!test.length&&!rating)return'';return`<section class="proof reveal"><div class="section proof-inner"><div class="proof-copy"><div class="kicker">${safe(t.experience)}</div><h2>${safe(d.trustLine||'')}</h2>${rating?`<div class="rating"><b>${safe(rating)}</b><span>★★★★★</span>${reviews?`<small>${safe(reviews)} reviews</small>`:''}</div>`:''}</div><div class="diff-grid">${dif.map((x,i)=>`<article><span>0${i+1}</span><h3>${safe(x.title)}</h3><p>${safe(x.text)}</p></article>`).join('')}</div>${stats.length?`<div class="stats-row">${stats.map(x=>`<div><b>${safe(x.title)}</b><span>${safe(x.text)}</span></div>`).join('')}</div>`:''}${test.length?`<div class="test-grid">${test.map(x=>`<blockquote><p>“${safe(x.text)}”</p><cite>${safe(x.title)}</cite></blockquote>`).join('')}</div>`:''}</div></section>`}
