function buildNicheFeature(l,d,t){if(l.nicheKey==='physio'||l.nicheKey==='chiropractor')return`<section class="process-band"><div class="section"><div class="kicker">Process</div><div class="process-row"><div><b>01</b><span>${langKey(l)==='en'?'Understand':'Entender'}</span></div><div><b>02</b><span>${langKey(l)==='en'?'Plan':'Planejar'}</span></div><div><b>03</b><span>${langKey(l)==='en'?'Move':'Mover'}</span></div><div><b>04</b><span>${langKey(l)==='en'?'Progress':'Evoluir'}</span></div></div></div></section>`;if(l.nicheKey==='aesthetics')return`<section class="signature"><div class="section"><span class="signature-line"></span><div><div class="kicker">${langKey(l)==='en'?'Signature experience':'Experiência'}</div><h2>${safe(d.trustLine)}</h2></div><p>${safe(d.sub)}</p></div></section>`;if(l.nicheKey==='salon')return`<div class="marquee"><div>STYLE · DETAIL · EXPERIENCE · ${safe(l.name)} · STYLE · DETAIL · EXPERIENCE · ${safe(l.name)} ·</div></div>`;if(l.nicheKey==='pet'||l.nicheKey==='veterinary')return`<section class="pet-band"><div class="section"><span>♡</span><h2>${safe(d.trustLine)}</h2><span>✦</span></div></section>`;if(['accounting','cleaning','landscaping','contractor'].includes(l.nicheKey))return`<section class="business-band"><div class="section"><div><b>01</b><span>${langKey(l)==='en'?'Clear scope':'Escopo claro'}</span></div><div><b>02</b><span>${langKey(l)==='en'?'Direct contact':'Contacto direto'}</span></div><div><b>03</b><span>${langKey(l)==='en'?'Professional presence':'Presença profissional'}</span></div></div></section>`;return''}
function buildContact(l,d,t){const w=K.waUrl(d.phone,l.country),map=d.map&&d.address?`<iframe loading="lazy" src="https://www.google.com/maps?q=${encodeURIComponent(d.address)}&output=embed"></iframe>`:'';return`<section class="section contact reveal" id="contact"><div class="contact-card"><div><div class="kicker">${safe(t.contact)}</div><h2>${safe(d.finalCta)}</h2><p>${safe(d.trustLine)}</p>${w?`<a class="btn primary" href="${attr(w)}" target="_blank">${safe(d.cta||t.whatsapp)} ↗</a>`:''}<div class="contact-list">${d.address?`<div><span>${safe(t.address)}</span><b>${safe(d.address)}</b></div>`:''}${d.phone?`<div><span>${safe(t.phone)}</span><b>${safe(d.phone)}</b></div>`:''}${d.hours?`<div><span>${safe(t.hours)}</span><b>${safe(d.hours).replace(/\n/g,'<br>')}</b></div>`:''}</div></div><div class="map">${map||`<div class="map-fallback">${safe(initials(l.name))}</div>`}</div></div></section>`}

